#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        int m = n-x-y;
        vector<int> np;
        // suffix: p[n-y .. n-1]
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        // middle: p[x .. x+m-1]
        for(int i=x;i<x+m;i++) np.push_back(p[i]);
        // prefix: p[0 .. x-1]
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    for(int target=0; target<n-2; target++){
        int val = target+1;
        int pos = -1;
        for(int i=target;i<n;i++) if(p[i]==val){pos=i;break;}
        if(pos==target) continue;

        // Move element from pos to target
        // If pos is not at end (n-1), first move it to end
        if(pos < n-1){
            // x = pos+1, y = n-1-pos, but need x+y < n => pos+1+n-1-pos = n, not < n
            // So use x = pos, y = n-1-pos if pos>0
            // Or x = pos+1, y = n-2-pos if pos < n-2
            if(pos > 0 && (n-1-pos) > 0 && pos + (n-1-pos) < n){
                // This doesn't work: pos + n-1-pos = n-1 < n. Good!
                // But x=pos means prefix is [0..pos-1], suffix is [pos+1..n-1]
                // Element at pos stays in middle? middle is p[pos..pos] if y=n-1-pos
                // x=pos, y=n-1-pos: suffix=[pos+1..n-1], middle=[pos], prefix=[0..pos-1]
                // Result: [pos+1..n-1, pos, 0..pos-1]. Element now at position n-1-pos... 
                // Let me just move to last: use two-step
            }
            int x1 = 1, y1 = n-1-pos;
            if(y1>0 && 1+y1<n){
                apply_op(x1, y1);
                for(int i=0;i<n;i++) if(p[i]==val){pos=i;break;}
            }
            if(pos<n-1 && pos>0){
                int x2=pos, y2=1;
                if(x2>0 && x2+1<n){ apply_op(x2,y2); pos=0; }
                for(int i=0;i<n;i++) if(p[i]==val){pos=i;break;}
            }
        }
        if(pos==target) continue;
        // Now place it at target
        int x=target, y=n-pos;
        if(target==0){ x=1; y=n-pos; if(x+y<n){ apply_op(x,y); apply_op(n-pos,1);} else{ apply_op(1,n-1-pos>0?n-1-pos:1);} for(int i=0;i<n;i++) if(p[i]==val){pos=i;break;} if(pos==target) continue;}
        else if(x>0 && y>0 && x+y<n){ apply_op(x,y); }
        else { if(pos!=target){int a=target+1,b=n-pos; if(a>0&&b>0&&a+b<n) apply_op(a,b);}}
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
